<script lang="ts">
 import { onMount } from 'svelte';
 import Icon from '#lib/components/Icon.svelte';
 import Fingerprint from '#lib/components/Fingerprint.svelte';
 import {decode,download,type Decoded} from '#lib/ingest.ts';
 import {privacy,observePrivacy,privacySnapshot} from '#lib/privacy.ts';
 import type {Region,Scan,Report,WorkerReply,Mode,WorkerRequest} from '../../../engine/src/types';
 import {landmarkRegions} from '../../../engine/src/regions';
 import type {IdentifierBox} from '#lib/ocr.ts';
 type Tab='scan'|'documents'|'proof'|'lab'|'why';
 type Sample={name:string;url:string;regions:Region[];document:boolean};
 const nav:{id:Tab;name:string;icon:string}[]=[{id:'scan',name:'Fingerprint scan',icon:'scan'},{id:'documents',name:'Documents',icon:'document'},{id:'proof',name:'Privacy proof',icon:'shield'},{id:'lab',name:'The lab',icon:'lab'},{id:'why',name:'Why Smudge',icon:'info'}];
 let tab=$state<Tab>('scan'),dark=$state(false),consent=$state(false),mode=$state<Mode>('photo');
 let image=$state<Decoded|null>(null),reference=$state<Decoded|null>(null),synthetic=$state(false),sameImage=$state(false);
 let regions=$state<Region[]>([]),scan=$state<Scan|null>(null),report=$state<Report|null>(null),resultUrl=$state(''),resultBlob:Blob|null=null;
 let busy=$state(false),message=$state(''),error=$state(''),progress=$state(0),showScore=$state(false),loupe=$state<Region|null>(null),compare=$state(50),drawing=$state(false),drawStart=$state<{x:number;y:number}|null>(null),draft=$state<Region|null>(null);
 let samples=$state<Sample[]>([]),benchmark=$state<any>(null),independent=$state<any>(null),recent=$state<{name:string;prints:number;ssim:number}[]>([]),identifiers=$state<IdentifierBox[]>([]),maskIds=$state(true),pdfFile:File|null=null,pages=$state(0),pdfPage=$state(1);
 let fileInput=$state<HTMLInputElement>(null!),referenceInput=$state<HTMLInputElement>(null!),cameraInput=$state<HTMLInputElement>(null!),photoArea=$state<HTMLDivElement>(null!);
 let pipeline:Worker|undefined,detector:Worker|undefined,requestId=0;
 let dragOver=$state(false),installed=$state(false),installPrompt:any=null;
 const selected=$derived(nav.find(n=>n.id===tab)!);
 const scanTab=$derived(tab==='scan'||tab==='documents');
 const matchMax=$derived(Math.max(60,...(scan?.prints.map(p=>p.score??0)??[]),...(report?.prints.flatMap(p=>[p.before.score??0,...p.attacks.map(a=>a.score)])??[])));
 onMount(()=>{
  observePrivacy();
  fetch('/samples/index.json').then(r=>r.json()).then(v=>samples=v).catch(()=>{});
  fetch('/benchmarks.json').then(r=>r.json()).then(v=>benchmark=v).catch(()=>{});
  fetch('/independent.json').then(r=>r.json()).then(v=>independent=v).catch(()=>{});
  dark=localStorage.getItem('smudge-theme')==='dark';
  const install=(e:Event)=>{e.preventDefault();installPrompt=e;};window.addEventListener('beforeinstallprompt',install);
  const shared=new URLSearchParams(location.search).get('shared');if(shared)readShared();
  return()=>{pipeline?.terminate();detector?.terminate();revoke();window.removeEventListener('beforeinstallprompt',install);};
 });
 function revoke(){if(image?.url)URL.revokeObjectURL(image.url);if(resultUrl)URL.revokeObjectURL(resultUrl);if(reference?.url)URL.revokeObjectURL(reference.url);}
 function theme(){dark=!dark;localStorage.setItem('smudge-theme',dark?'dark':'light');}
 function navigate(id:Tab){tab=id;error='';if(id==='documents')mode='document';else if(id==='scan'&&mode==='document')mode='photo';}
 function reset(){mode=tab==='documents'?'document':'photo';pipeline?.terminate();pipeline=undefined;detector?.terminate();detector=undefined;busy=false;revoke();image=null;reference=null;regions=[];scan=null;report=null;resultUrl='';resultBlob=null;synthetic=false;sameImage=false;error='';message='';identifiers=[];pages=0;pdfPage=1;pdfFile=null;loupe=null;}
 async function readShared(){try{const cache=await caches.open('smudge-share');const r=await cache.match('/shared-image');if(r){const b=await r.blob();await cache.delete('/shared-image');consent=false;message='A photo was shared to Smudge. Confirm permission before scanning.';await loadFile(new File([b],r.headers.get('x-filename')??'shared-photo.jpg',{type:b.type}),true);}}catch{error='Could not open the shared image. Choose it from your gallery.';}}
 async function loadFile(file:File,fromShare=false){
  if(!consent&&!fromShare){error='Confirm you own this image or have permission to process it.';return;}
  reset();busy=true;message='Opening your image on this device';
  try{image=await decode(file);if(file.type==='application/pdf'||file.name.endsWith('.pdf')){pdfFile=file;pages=(image as Decoded&{pages?:number}).pages??1;mode='document';tab='documents';}message='Image loaded. Find fingertips or select a region yourself.';}
  catch(e){error=String(e instanceof Error?e.message:e);}finally{busy=false;}
 }
 async function picked(e:Event){const el=e.currentTarget as HTMLInputElement;const file=el.files?.[0];if(file)await loadFile(file);el.value='';}
 async function pickedReference(e:Event){const el=e.currentTarget as HTMLInputElement,file=el.files?.[0];el.value='';if(!file)return;try{if(reference)URL.revokeObjectURL(reference.url);reference=await decode(file);if(Math.max(reference.width,reference.height)>1024){URL.revokeObjectURL(reference.url);reference=null;throw new Error('Crop the reference to a single fingertip, up to 1024 pixels per side.');}scan=null;report=null;message='Reference enrolled in memory. Select the same finger in your photo.';}catch(e){error=(e as Error).message;}}
 async function example(sample:Sample){
  reset();busy=true;tab=sample.document?'documents':'scan';mode=sample.document?'document':'closeup';
  try{const b=await fetch(sample.url).then(r=>{if(!r.ok)throw new Error('The example is not cached yet. Reconnect once and try again.');return r.blob();});image=await decode(new File([b],sample.name+'.png',{type:'image/png'}));regions=sample.regions;synthetic=true;sameImage=true;message='Synthetic specimen loaded. No human fingerprints. Ready to analyse.';}
  catch(e){error=(e as Error).message;}finally{busy=false;}
 }
 async function nextPdfPage(value:number){if(!pdfFile)return;busy=true;try{const d=await decode(pdfFile,value);if(image)URL.revokeObjectURL(image.url);image=d;pdfPage=value;regions=[];scan=null;report=null;identifiers=[];if(resultUrl)URL.revokeObjectURL(resultUrl);resultUrl='';resultBlob=null;message='Select the thumb impressions on this page. Export covers this page only.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function detect(){
  if(!image)return;busy=true;error='';scan=null;report=null;message=mode==='document'?'Looking for ridge-like document texture':'Finding hands on this device';
  try{
   if(mode==='closeup'){const w=Math.min(image.width,1024),h=Math.min(image.height,1024);regions=[{id:'closeup',x:Math.round((image.width-w)/2),y:Math.round((image.height-h)/2),w,h,label:'Close-up print',source:'manual'}];}
   else if(mode==='document'){const worker=new Worker(new URL('../lib/workers/document.worker.ts',import.meta.url),{type:'module'});const data={pixels:new Uint8ClampedArray(image.pixels),width:image.width,height:image.height};regions=await new Promise<Region[]>((resolve,reject)=>{worker.onmessage=e=>{worker.terminate();e.data.error?reject(new Error(e.data.error)):resolve(e.data.regions);};worker.onerror=()=>{worker.terminate();reject(new Error('Document detection failed. Select the impression manually.'));};worker.postMessage(data,[data.pixels.buffer]);});message=regions.length?'Texture candidates found. Remove text or non-print regions before scanning.':'No candidates found. Select the thumb impression manually.';}
   else{
    const scale=Math.min(1,2048/Math.max(image.width,image.height)),bitmap=await createImageBitmap(new ImageData(new Uint8ClampedArray(image.pixels),image.width,image.height),{resizeWidth:Math.round(image.width*scale),resizeHeight:Math.round(image.height*scale)});
    detector??=new Worker('/detect-worker.js');
    const value:any=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{detector?.terminate();detector=undefined;reject(new Error('The hand detector took too long. Select a fingertip manually.'));},45000);detector!.onmessage=e=>{clearTimeout(timeout);e.data.error?reject(new Error(e.data.error)):resolve(e.data);};detector!.onerror=()=>{clearTimeout(timeout);reject(new Error('The hand detector could not start. Select a fingertip manually.'));};detector!.postMessage({bitmap},[bitmap]);});
    const found=landmarkRegions(value.landmarks,value.handedness,image.width,image.height);regions=found.regions;message=regions.length?`${regions.length} fingertip candidates. Check that the ridged side is visible, and remove any incorrect regions.${found.uncertain?' Palm direction is uncertain; check both sides carefully.':''}`:'No hands found. Choose a clear photo, or select a fingertip manually.';
   }
  }catch(e){error=(e as Error).message;}finally{busy=false;}
 }
 function selectStart(e:PointerEvent){if(!drawing||busy||!image)return;const r=photoArea.getBoundingClientRect();drawStart={x:Math.round((e.clientX-r.left)/r.width*image.width),y:Math.round((e.clientY-r.top)/r.height*image.height)};photoArea.setPointerCapture(e.pointerId);}
 function selectMove(e:PointerEvent){if(!drawStart||!image)return;const r=photoArea.getBoundingClientRect(),x=Math.max(0,Math.min(image.width,Math.round((e.clientX-r.left)/r.width*image.width))),y=Math.max(0,Math.min(image.height,Math.round((e.clientY-r.top)/r.height*image.height)));draft={id:'manual-'+Date.now(),x:Math.min(x,drawStart.x),y:Math.min(y,drawStart.y),w:Math.abs(x-drawStart.x),h:Math.abs(y-drawStart.y),label:'Selected print '+(regions.length+1),source:'manual'};}
 function selectEnd(){if(draft){if(draft.w<32||draft.h<32||draft.w>1024||draft.h>1024)error='Select an area from 32 to 1024 pixels per side, closely around the print.';else if(regions.length>=20)error='Select at most 20 regions.';else{regions=[...regions,draft];scan=null;report=null;error='';}draft=null;}drawStart=null;drawing=false;}
 function addCentre(){if(!image||busy)return;const w=Math.min(192,image.width),h=Math.min(240,image.height);regions=[...regions,{id:'manual-'+Date.now(),x:Math.round((image.width-w)/2),y:Math.round((image.height-h)/2),w,h,label:'Selected print '+(regions.length+1),source:'manual'}];scan=null;report=null;}
 function removeRegion(id:string){regions=regions.filter(r=>r.id!==id);scan=null;report=null;}
 function request(type:'scan'|'smudge'):Promise<WorkerReply>{
  if(!image)throw new Error('Choose an image first.');
  pipeline??=new Worker(new URL('../lib/workers/pipeline.worker.ts',import.meta.url),{type:'module'});
  const id=++requestId,req:WorkerRequest={id,type,pixels:new Uint8ClampedArray(image.pixels),width:image.width,height:image.height,regions:$state.snapshot(regions),synthetic,sameImage,identifierMasks:maskIds?$state.snapshot(identifiers).map(({x,y,w,h})=>({x,y,w,h})):[],reference:reference?{pixels:new Uint8ClampedArray(reference.pixels),width:reference.width,height:reference.height}:undefined};
  return new Promise((resolve,reject)=>{
   pipeline!.onmessage=(e:MessageEvent<WorkerReply>)=>{if(e.data.id!==id)return;if(e.data.type==='progress'){message=e.data.message;progress=e.data.progress;}else if(e.data.type==='error')reject(new Error(e.data.message));else resolve(e.data);};
   pipeline!.onerror=()=>{pipeline?.terminate();pipeline=undefined;reject(new Error('The engine stopped. Try fewer regions or a smaller image.'));};
   const transfer:Transferable[]=[req.pixels.buffer];if(req.reference)transfer.push(req.reference.pixels.buffer);pipeline!.postMessage(req,transfer);
  });
 }
 async function run(type:'scan'|'smudge'){
  if(!synthetic&&!consent){error='Confirm you have permission to process this image.';return;}
  if(!regions.length){error='Find fingertips or select a print region first.';return;}
  busy=true;error='';progress=0;
  try{
   const result=await request(type);
   if(result.type==='scan'){scan=result.scan;message=`Analysis complete. ${result.scan.prints.reduce((n,p)=>n+p.highQuality,0)} reliable ridge points across ${regions.length} selected regions.`;}
   if(result.type==='smudge'&&image){
    result.report.privacy=privacySnapshot();report=result.report;resultBlob=result.blob;if(resultUrl)URL.revokeObjectURL(resultUrl);resultUrl=URL.createObjectURL(resultBlob);compare=50;
    recent=[{name:image.name,prints:regions.length,ssim:report.ssim},...recent].slice(0,4);
    message=report.prints.every(p=>p.passed)?'Treatment complete. The tested matcher variants no longer accept these prints against the selected reference.':'Treatment complete. Verification is incomplete. Check each result before sharing.';
   }
  }catch(e){error=(e as Error).message;}finally{busy=false;}
 }
 function cancel(){pipeline?.terminate();pipeline=undefined;detector?.terminate();detector=undefined;busy=false;message='Processing cancelled. Your original image is unchanged.';}
 async function readText(){if(!image)return;busy=true;error='';try{const {detectIdentifiers}=await import('#lib/ocr.ts');identifiers=await detectIdentifiers(image.pixels,image.width,image.height,s=>message=s);message=identifiers.length?`${identifiers.length} checksum-valid identifier${identifiers.length===1?'':'s'} found. Review the marked areas; OCR can miss text.`:'No checksum-valid identifiers found. This does not prove the document contains none. Check it visually.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function share(){if(!resultBlob)return;const f=new File([resultBlob],'smudge-photo.jpg',{type:'image/jpeg'});try{if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:'Smudge photo'});else download(resultBlob,'smudge-photo.jpg');}catch(e){if((e as Error).name!=='AbortError')error='Sharing is unavailable. Use Download photo instead.';}}
 function saveReport(){if(!report)return;const clean={...$state.snapshot(report),prints:report.prints.map(p=>({...p,before:{...p.before,minutiae:undefined},after:{...p.after,minutiae:undefined}})),privacy:privacySnapshot()};download(new Blob([JSON.stringify(clean,null,2)],{type:'application/json'}),'smudge-report.json');}
 async function install(){if(installPrompt){await installPrompt.prompt();const r=await installPrompt.userChoice;installed=r.outcome==='accepted';installPrompt=null;}else message='To install, open your browser menu and choose “Install app” or “Add to Home Screen”.';}
 function focusModal(node:HTMLDivElement){
  const previous=document.activeElement as HTMLElement|null;queueMicrotask(()=>node.querySelector<HTMLButtonElement>('button')?.focus());
  const key=(e:KeyboardEvent)=>{if(e.key!=='Tab')return;const els=[...node.querySelectorAll<HTMLElement>('button,a[href],input,select,[tabindex="0"]')].filter(el=>!el.hasAttribute('disabled'));const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}};
  node.addEventListener('keydown',key);return{destroy(){node.removeEventListener('keydown',key);previous?.focus();}};
 }
 function pct(n:number){return (n*100).toFixed(1);}
</script>

<svelte:head><title>Smudge — Your fingerprint. Yours to keep.</title><meta name="description" content="Find exposed fingerprints, reduce ridge detail, and inspect real NIST matcher results. Photos stay on your device."/></svelte:head>
<div class:dark class="app-shell">
 <a href="#workspace" class="skip-link">Skip to workspace</a>
 <aside class="sidebar">
  <a class="brand" href="/" aria-label="Smudge home"><span class="brand-mark"><Icon name="finger" size={28}/></span>smudge<span class="brand-period">.</span></a>
  <div class="rail-caption">A little less trace.</div>
  <nav aria-label="Main navigation">{#each nav as item}<button class:nav-active={tab===item.id} onclick={()=>navigate(item.id)} aria-current={tab===item.id?'page':undefined}><Icon name={item.icon}/><span>{item.name}</span>{#if tab===item.id}<span class="nav-dot"></span>{/if}</button>{/each}</nav>
  <div class="rail-bottom"><div class="local-emblem"><Icon name="lock" size={24}/></div><strong>Your photos stay yours.</strong><p>Processed on this device.<br/>Never uploaded.</p><button class="rail-link" onclick={()=>navigate('proof')}>See the privacy proof <Icon name="arrow" size={15}/></button><div class="rail-footer"><span>Smudge / v1.0</span><span class="live-dot"></span></div></div>
 </aside>
 <div class="main-shell">
  <header class="topbar"><div class="breadcrumb">Your workspace <Icon name="chevron" size={14}/> <span>{selected.name}</span></div><div class="top-actions"><span class="local-badge"><span class="live-dot"></span>{$privacy.offline?'Offline mode':'On-device only'}</span><button class="icon-button theme-button" onclick={theme} aria-label={dark?'Switch to light theme':'Switch to dark theme'}><Icon name={dark?'sun':'moon'} size={19}/></button><span class="avatar" role="img" aria-label="Private local session"><Icon name="finger" size={22}/></span></div></header>
  <main id="workspace" tabindex="-1">
   {#if scanTab}
    <section class="page-intro"><div><div class="intro-kicker"><span class="small-line"></span>{tab==='documents'?'Document privacy, on your terms':'Personal privacy, by design'}</div><h1>{tab==='documents'?'Leave less on paper.':image?'Every ridge tells a story.':'Some things are yours to keep.'}</h1><p>{tab==='documents'?'Find thumb impressions and mask checksum-valid identifiers in scanned pages.':image?'See what your photo reveals. Then choose what it keeps.':'You can change a password. You can’t change your fingerprint.'}</p></div>{#if image}<button class="button secondary new-scan" onclick={reset} disabled={busy}><Icon name="plus" size={17}/> New scan</button>{:else}<span class="intro-note"><Icon name="shield" size={16}/> No account. No upload.</span>{/if}</section>
    {#if error}<div class="notice error" role="alert"><Icon name="info"/>{error}<button class="icon-button" onclick={()=>error=''} aria-label="Dismiss error"><Icon name="close" size={16}/></button></div>{/if}
    {#if message&&!busy}<p class="status-message" role="status">{message}</p>{/if}
    <div class="workbench" class:has-image={!!image}>
     <section class="scan-card" aria-label="Fingerprint scanner">
      <div class="scan-card-top"><span class="scanner-state"><span class="live-dot"></span>{report?'Treatment review':scan?'Analysis complete':image?'Image ready':'Ready when you are'}</span><span class="scanner-meta">{image?`${image.width} × ${image.height}`:'Fingerprint privacy lab'}</span></div>
      {#if image}
       <div class="loaded-viewport">
        <div class:drawing bind:this={photoArea} class="photo-area" role="group" aria-label="Photo with selected print regions" onpointerdown={selectStart} onpointermove={selectMove} onpointerup={selectEnd} onpointercancel={()=>{draft=null;drawStart=null;drawing=false;}}>
         <img class="source-image" src={image.url} alt="Your selection, processed only on this device" draggable="false"/>
         {#if resultUrl}<img class="result-image" src={resultUrl} alt="After ridge suppression" style:clip-path={`inset(0 ${100-compare}% 0 0)`}/><span class="comparison-divider" style:left={`${compare}%`}></span><span class="comparison-label after">After</span><span class="comparison-label before">Before</span>{:else}
          {#each regions as r,i}<button class="region-box" style:left={`${r.x/image.width*100}%`} style:top={`${r.y/image.height*100}%`} style:width={`${r.w/image.width*100}%`} style:height={`${r.h/image.height*100}%`} aria-label={`Inspect ${r.label}`} onclick={()=>{if(!drawing)loupe=r;}}><span>{i+1}</span>{#if scan}{#each scan.prints[i]?.minutiae.filter(m=>m.reliability>=.5)??[] as m}<i class="minutia-dot" style:left={`${m.x/r.w*100}%`} style:top={`${m.y/r.h*100}%`}></i>{/each}{/if}</button>{/each}
          {#if draft}<div class="region-box draft" style:left={`${draft.x/image.width*100}%`} style:top={`${draft.y/image.height*100}%`} style:width={`${draft.w/image.width*100}%`} style:height={`${draft.h/image.height*100}%`}></div>{/if}
          {#each identifiers as box}<div class="identifier-box" style:left={`${box.x/image.width*100}%`} style:top={`${box.y/image.height*100}%`} style:width={`${box.w/image.width*100}%`} style:height={`${box.h/image.height*100}%`}><span>Mask ···· {box.last4}</span></div>{/each}
         {/if}
        </div>
       </div>
       {#if resultUrl}<div class="compare-control"><span>After</span><input aria-label="Before and after comparison" type="range" min="0" max="100" bind:value={compare}/><span>Before</span></div>{:else}<div class="image-toolbar"><span class="image-name" title={image.name}>{image.name}</span><button class="scanner-button" disabled={busy} onclick={()=>drawing=!drawing}><Icon name="crop" size={16}/>{drawing?'Drag over a print':'Select region'}</button><button class="scanner-button" disabled={busy||regions.length>=20} onclick={addCentre} title="Add a centre region; adjust its coordinates below"><Icon name="plus" size={16}/> Add region</button></div>{/if}
      {:else}
       <div class="scanner-hero"><div class="scan-grid"></div><div class="scan-ring one"></div><div class="scan-ring two"></div><div class="scan-crosshair tl"></div><div class="scan-crosshair tr"></div><div class="scan-crosshair bl"></div><div class="scan-crosshair br"></div><div class="hero-fingerprint"><Fingerprint active={busy}/></div><span class="scanner-coordinate coord-left">Ridge identity<br/><strong>One of a kind.</strong></span><span class="scanner-coordinate coord-right">Your next scan<br/><strong>Stays right here.</strong></span><span class="scan-art-label">Illustrative ridge artwork</span></div>
       <div class="scan-card-bottom"><span><Icon name="finger" size={17}/> Your fingerprint is not a password.</span><span>You only get one.</span></div>
      {/if}
      {#if busy}<div class="processing"><div class="processing-top"><span class="spinner"></span><span aria-live="polite">{message}</span><button class="scanner-button" onclick={cancel}>Cancel</button></div><progress value={progress||.04} max="1" aria-label="Processing progress"></progress></div>{/if}
     </section>
     <section class="action-panel">
      {#if report}
       <div class="panel-heading"><span class="round-icon"><Icon name={report.prints.every(p=>p.passed)?'check':'info'} size={22}/></span><span class="subtle-label">The results are in</span></div><h2>{report.prints.every(p=>p.passed)?'Less trace. More you.':'A smudge, with limits.'}</h2><p>{report.prints.every(p=>p.passed)?'Every tested variant fell below the provisional match line. Review what that means below.':'Ridge detail was reduced. This image has not passed every verification check.'}</p>
       <div class="result-readout"><div><span>Image similarity</span><strong>{pct(report.ssim)}<small>%</small></strong></div><Icon name="finger" size={46}/></div><p class="fine-print">Measured on your exported JPEG. Similarity is not a safety score.</p>
       <button class="button primary full" onclick={()=>resultBlob&&download(resultBlob,'smudge-photo.jpg')}><Icon name="download" size={18}/> Download photo</button><div class="two-actions"><button class="button secondary" onclick={saveReport}><Icon name="document" size={17}/> Report</button><button class="button secondary" onclick={share}><Icon name="share" size={17}/> Share</button></div><button class="text-button" onclick={()=>{report=null;resultUrl&&URL.revokeObjectURL(resultUrl);resultUrl='';resultBlob=null;}}>Back to regions</button>
      {:else if scan}
       <div class="panel-heading"><span class="round-icon"><Icon name="finger" size={22}/></span><span class="subtle-label">A closer look</span></div><h2>{scan.prints.reduce((n,p)=>n+p.highQuality,0)>0?'Your photo has ridge detail.':'No reliable ridge points found.'}</h2><p>{scan.prints.length} selected {scan.prints.length===1?'region':'regions'}. {scan.referenceKind==='none'?'No reference enrolled. Match verification is unavailable.':scan.referenceKind==='same-image'?'Synthetic example uses a same-image baseline, not an independently captured reference.':'Compared against your supplied close-up.'}</p>
       <div class="ridge-total"><strong>{scan.prints.reduce((n,p)=>n+p.highQuality,0)}</strong><span>reliable ridge points<br/>found by NIST mindtct</span></div><button class="button primary full" disabled={busy} onclick={()=>run('smudge')}><Icon name="finger" size={19}/> Smudge selected prints <Icon name="arrow" size={18}/></button><p class="fine-print">Suppress ridge detail, then re-test enhancement, sharpening, upscaling and JPEG variants.</p>
      {:else}
       <div class="panel-heading"><span class="round-icon"><Icon name={tab==='documents'?'document':'scan'} size={22}/></span><span class="subtle-label">A little smudge. A lot more privacy.</span></div><h2>{image?'Let’s look a little closer.':'Before you share, Smudge.'}</h2><p>{image?'Check the selected regions, then find out how much fingerprint detail they reveal.':'A thumbs-up. A peace sign. The details in your photos can reveal more than you think.'}</p>
       {#if !image}
        <div class:drag-over={dragOver} class="dropzone" role="region" aria-label="Photo upload drop zone" ondragover={e=>{e.preventDefault();dragOver=true;}} ondragleave={()=>dragOver=false} ondrop={e=>{e.preventDefault();dragOver=false;const f=e.dataTransfer?.files[0];if(f)loadFile(f);}}><span class="upload-icon"><Icon name="upload" size={27}/></span><strong>Drop a {tab==='documents'?'document':'photo'} here</strong><span>or choose one from your device</span><small>{tab==='documents'?'PDF, JPEG or PNG':'JPEG, PNG or WebP'} · up to 45 MB</small></div>
        <label class="consent"><input type="checkbox" bind:checked={consent}/><span>I own this image or have permission to process it.</span></label><button class="button primary full" onclick={()=>fileInput.click()} disabled={busy}><Icon name="plus" size={18}/> Choose {tab==='documents'?'document':'photo'} <Icon name="arrow" size={18}/></button><button class="text-button camera-button" onclick={()=>cameraInput.click()} disabled={busy}><Icon name="camera" size={17}/> Take a photo</button>
       {:else}
        {#if !synthetic}<label class="consent"><input type="checkbox" bind:checked={consent}/><span>I own this image or have permission to process it.</span></label>{/if}
        <label class="field-label" for="mode">Image type</label><select id="mode" bind:value={mode} disabled={busy}><option value="photo">Hand photo</option><option value="closeup">Fingerprint close-up</option><option value="document">Scanned document</option></select>
        <button class="button secondary full" disabled={busy} onclick={detect}><Icon name="scan" size={18}/>{mode==='photo'?'Find fingertips':mode==='document'?'Find print candidates':'Select centre print'}</button>
        <div class="reference-row"><div><strong>Reference close-up</strong><span>{reference?reference.name:'Optional · one matching finger'}</span></div><button class="icon-button" onclick={()=>referenceInput.click()} disabled={busy} aria-label="Enrol a reference close-up"><Icon name="plus" size={19}/></button></div>{#if reference}<button class="text-button" onclick={()=>{URL.revokeObjectURL(reference!.url);reference=null;scan=null;}}>Remove reference</button>{/if}
        <button class="button primary full" disabled={busy||!regions.length} onclick={()=>run('scan')}>Analyse {regions.length||'selected'} {regions.length===1?'print':'prints'} <Icon name="arrow" size={18}/></button><p class="fine-print">Review regions first. Automatic suggestions can miss prints or include the back of a finger.</p>
       {/if}
      {/if}
      <div class="panel-privacy"><Icon name="lock" size={14}/><span>No photos leave your device.</span><button onclick={()=>navigate('proof')} aria-label="Inspect privacy proof"><Icon name="info" size={15}/></button></div>
     </section>
    </div>
    <input bind:this={fileInput} type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif,application/pdf" onchange={picked} class="visually-hidden" tabindex="-1" aria-label="Choose image file"/>
    <input bind:this={cameraInput} type="file" accept="image/*" capture="environment" onchange={picked} class="visually-hidden" tabindex="-1" aria-label="Take a photo"/>
    <input bind:this={referenceInput} type="file" accept="image/*" onchange={pickedReference} class="visually-hidden" tabindex="-1" aria-label="Choose reference close-up"/>
    {#if image&&pages>1}<div class="pdf-pages"><span>PDF page</span><select aria-label="PDF page" value={pdfPage} onchange={e=>nextPdfPage(Number(e.currentTarget.value))} disabled={busy}>{#each Array(pages) as _,i}<option value={i+1}>{i+1} of {pages}</option>{/each}</select><span>Each page is processed and exported separately.</span></div>{/if}
    {#if image&&mode==='document'&&!report}<div class="document-tools"><div><Icon name="document"/><div><strong>More than a fingerprint?</strong><p>Find checksum-valid Aadhaar-like numbers with local OCR. Masks the first eight digits.</p></div></div><button class="button secondary" onclick={readText} disabled={busy}>Check identifiers</button>{#if identifiers.length}<label class="consent"><input type="checkbox" bind:checked={maskIds}/>Mask {identifiers.length} detected identifiers on export</label>{/if}</div>{/if}
    {#if image&&regions.length&&!report}<section class="region-review"><div class="section-heading"><h3>Selected print regions <span>{regions.length}</span></h3><p>Inspect, adjust, or remove a region before analysis.</p></div><div class="region-list">{#each regions as r,i}<div class="region-row"><button class="region-id" onclick={()=>loupe=r} aria-label={`Inspect ${r.label}`}>{i+1}</button><div class="region-name"><strong>{r.label}</strong><span>{r.source==='synthetic'?'Synthetic texture':r.source==='manual'?'Manually selected':'Review suggested region'}</span></div><div class="region-coordinates">{#each ['x','y','w','h'] as key}<label>{key}<input type="number" min={key==='w'||key==='h'?32:0} max={key==='w'||key==='h'?1024:key==='x'?image.width:image.height} value={r[key as 'x'|'y'|'w'|'h']} disabled={busy} onchange={e=>{regions=regions.map(v=>v.id===r.id?{...v,[key]:Math.round(Number(e.currentTarget.value))}:v);scan=null;}}/></label>{/each}</div><button class="icon-button" disabled={busy} onclick={()=>removeRegion(r.id)} aria-label={`Remove ${r.label}`}><Icon name="trash" size={18}/></button></div>{/each}</div></section>{/if}
    {#if scan&&!report}<section class="analysis-section"><div class="section-heading"><h3>What the scan found</h3><button class="text-button" onclick={()=>showScore=true}><Icon name="info" size={15}/> How we score</button></div><div class="analysis-grid">{#each scan.prints as p}<article class="analysis-card"><div class="analysis-title"><strong>{p.region.label}</strong><span class:risk={p.exposure>=45} class="tier">{p.tier} detail</span></div><div class="exposure-number">{p.exposure}<span>/100</span></div><p>Exposure heuristic</p><div class="measurement-row"><span>Reliable ridge points</span><strong>{p.highQuality}</strong></div><div class="measurement-row"><span>Coherent ridge area</span><strong>{pct(p.coherence)}%</strong></div>{#if p.score!==null}<div class="measurement-row"><span>Bozorth3 score</span><strong>{p.score}</strong></div><div class="match-track"><span style:width={`${Math.min(100,p.score/matchMax*100)}%`}></span><i style:left={`${40/matchMax*100}%`}></i></div><p class="fine-print">Match line 40 · provisional, uncalibrated{scan.referenceKind==='same-image'?' · same-image diagnostic':''}</p>{:else}<div class="no-reference"><Icon name="info" size={15}/> No reference. No match score.</div>{/if}</article>{/each}</div></section>{/if}
    {#if report}<section class="verification-section"><div class="section-heading"><h3>The verification, in detail</h3><button class="text-button" onclick={saveReport}>Download evidence <Icon name="download" size={15}/></button></div><div class="notice" role="status"><Icon name="info"/>Threshold 40 is provisional. {report.referenceKind==='same-image'?'These are synthetic, same-image comparisons.':report.referenceKind==='none'?'No reference enrolled. Attack scores below compare to the original region as a diagnostic only.':'Scores compare against your supplied reference.'} Results are not a guarantee against fingerprint theft.</div>{#each report.prints as p}<article class="verification-card"><div class="verification-title"><div><span class="subtle-label">{p.before.region.label}</span><h4>{p.passed?'Tested variants below the match line':report.referenceKind==='none'?'Reference needed for verification':'Not fully neutralised'}</h4></div><span class:warning={!p.passed} class="verification-badge"><Icon name={p.passed?'check':'info'} size={16}/>{p.passed?'Diagnostic passed':'Review needed'}</span></div><div class="before-after-stats"><div><span>Reliable points</span><strong>{p.before.highQuality}<Icon name="arrow" size={20}/>{p.after.highQuality}</strong></div><div><span>Match score</span><strong>{p.before.score??'—'}<Icon name="arrow" size={20}/>{p.after.score??'—'}</strong></div><div><span>Verification passes</span><strong>{p.passes}<small> / 3</small></strong></div></div><div class="attacker-table"><div class="attacker-header"><span>Attacker variant</span><span>Score / line 40</span><span>Reliable points</span></div>{#each p.attacks as a}<div class="attacker-row"><span>{a.name}</span><span class:failed={a.score>=40}>{a.score}<span class="mini-bar"><i style:width={`${Math.min(100,a.score/matchMax*100)}%`}></i></span></span><span>{a.highQuality}</span></div>{/each}</div>{#if !p.passed}<p class="result-warning">{report.referenceKind==='none'?'Enrol a clear close-up to compare the same finger, or crop the print out before sharing.':'Crop out this fingertip or retake the photo with the ridged side hidden.'}</p>{/if}</article>{/each}</section>{/if}
    {#if !image}<section class="samples-section"><div class="section-heading"><div><h3>Curious? Start with a specimen.</h3><p>Made-up ridges. Real processing. No personal photos needed.</p></div><span class="sample-label">Synthetic examples</span></div><div class="sample-grid">{#each samples as s,i}<button class="sample-card" disabled={busy} onclick={()=>example(s)}><span class="sample-thumb"><img src={s.url} alt=""/></span><span><strong>{s.name}</strong><small>{s.document?'Ink impression on a specimen page':i===1?'Two selected regions, one local scan':'A single ridge texture to explore'}</small></span><span class="sample-arrow"><Icon name="arrow" size={18}/></span></button>{/each}</div></section>{/if}
    <section class="how-strip" aria-label="How Smudge works"><div class="how-title"><Icon name="shield" size={23}/><span>A small step<br/><strong>before you share.</strong></span></div><div><span class="step-no">1</span><span><strong>Find the detail</strong><small>Locate exposed print regions.</small></span></div><div><span class="step-no">2</span><span><strong>Break the pattern</strong><small>Suppress identifiable ridge detail.</small></span></div><div><span class="step-no">3</span><span><strong>Check the difference</strong><small>Inspect actual matcher results.</small></span></div></section>
    {#if recent.length&&!image}<section class="recent"><h3>This session</h3>{#each recent as r}<div><span>{r.name}</span><span>{r.prints} regions · {pct(r.ssim)}% similarity</span></div>{/each}<p class="fine-print">Only these summary measurements are held in memory. Reloading clears them.</p></section>{/if}
   {:else if tab==='proof'}
    <section class="page-intro"><div><div class="intro-kicker"><span class="small-line"></span>Trust is good. Proof is better.</div><h1>Your photo never checks out.</h1><p>Local processing, inspectable policies, and an app that can work offline.</p></div><span class="intro-note"><Icon name="lock" size={16}/> No upload endpoint</span></section>
    <div class="proof-hero"><div><span class="proof-icon"><Icon name="shield" size={40}/></span><h2>On your device.<br/>Under your control.</h2><p>The photo lives in browser memory. Detection, NIST matching, and ridge suppression happen here. Shared files use a one-time local handoff cache, cleared when opened.</p></div><div class="proof-counter"><strong>{$privacy.external}</strong><span>observed external resource requests</span><small>Since this page opened · {$privacy.requests} same-page resources observed<br/>Resource timing is an audit aid, not an exhaustive proof.</small></div></div>
    <div class="proof-columns"><section class="plain-panel"><h3>What your browser is doing</h3><div class="policy-status"><Icon name={$privacy.headers['content-security-policy']&&$privacy.headers['content-security-policy']!=='Not delivered'?'check':'info'}/><div><strong>Content Security Policy</strong><p>{$privacy.headers['content-security-policy']&&$privacy.headers['content-security-policy']!=='Not delivered'?'Response policy delivered. It restricts connections to this origin.':'No response header detected. A built production page also includes SvelteKit’s CSP meta policy.'}</p></div></div><div class="policy-status"><Icon name="info"/><div><strong>Connection Allowlist</strong><p>{$privacy.headers['connection-allowlist']&&$privacy.headers['connection-allowlist']!=='Not delivered'?'Header delivered. Browser enforcement support is not inferred from its presence.':'No header detected. Start the production preview or use the included hosting configuration.'}</p></div></div><div class="policy-status"><Icon name={$privacy.cacheReady?'check':'download'}/><div><strong>{$privacy.cacheReady?'Ready for offline use':'Preparing offline assets'}</strong><p>{$privacy.cacheReady?'The app, engine, detector and OCR models are cached. Turn on airplane mode and try a specimen.':$privacy.cacheError||'The first visit downloads self-hosted models. Keep this page open until caching finishes.'}</p></div></div><div class="policy-status"><Icon name="eye"/><div><strong>{$privacy.blocked} policy violations observed</strong><p>Browser policy violation events are counted separately from completed resource requests.</p></div></div><button class="button secondary full" onclick={install}><Icon name="download" size={18}/>{installed?'App installed':'Install Smudge'}</button></section><section class="plain-panel headers-panel"><h3>The actual response headers</h3><p>Read with a same-origin HEAD request. Missing headers are shown as missing.</p>{#each Object.entries($privacy.headers) as [key,value]}<div class="header-entry"><span>{key}</span><code>{value}</code></div>{:else}<p>Headers unavailable. Reconnect and reload the page to inspect them.</p>{/each}</section></div>
    <section class="plain-panel devtools"><Icon name="eye" size={28}/><div><h3>Check it yourself.</h3><p>Open browser developer tools, choose <strong>Network</strong>, clear the log, then run a scan. Inspect request methods and bodies. All resources should come from this origin, with no photo-upload requests. Then switch Network to Offline and repeat.</p><p class="fine-print">Chrome / Edge: Ctrl+Shift+J on Windows, or ⌘⌥J on macOS. A website cannot open DevTools for you. Extensions, browser telemetry, and operating-system activity are outside this counter.</p></div></section>
   {:else if tab==='lab'}
    <section class="page-intro"><div><div class="intro-kicker"><span class="small-line"></span>Evidence, with the edges left in.</div><h1>Show the working.</h1><p>Reproducible tests. Real measurements. Clear limits.</p></div><a class="button secondary" href="/benchmarks.json" download><Icon name="download" size={17}/> Source data</a></section>
    <section class="lab-intro"><div><span class="pill">Synthetic evaluation</span><h2>A working engine.<br/>An honest starting point.</h2><p>These tests use procedural ridge textures, not real human fingerprints. They check the processing and matching loop. They cannot establish protection for people.</p><div class="pipeline-path"><span>Ridge texture</span><Icon name="arrow" size={16}/><span>NIST mindtct</span><Icon name="arrow" size={16}/><span>Bozorth3</span><Icon name="arrow" size={16}/><span>Smudge + re-test</span></div></div><div class="lab-stamp"><Icon name="lab" size={40}/><strong>No invented numbers.</strong><span>Generated by <code>make eval</code><br/>Committed alongside the source.</span></div></section>
    {#if benchmark}<div class="benchmark-summary"><div><span>Synthetic samples</span><strong>{benchmark.summary.sampleCount}</strong></div><div><span>Same-image matches before</span><strong>{benchmark.summary.baselineMatches}<small> / {benchmark.summary.sampleCount}</small></strong></div><div><span>Same-image matches after</span><strong>{benchmark.summary.afterMatches}<small> / {benchmark.summary.sampleCount}</small></strong></div><div><span>Mean ROI similarity</span><strong>{pct(benchmark.summary.meanRoiSSIM)}<small>%</small></strong></div></div><section class="plain-panel chart-panel"><div class="section-heading"><div><h3>Matching before and after treatment</h3><p>Native Bozorth3 scores. Same-image synthetic baseline. Plain enhancement only.</p></div><div class="chart-legend"><span><i></i>Before</span><span><i></i>After</span></div></div><div class="score-chart">{#each benchmark.samples as row}<div class="chart-column"><div class="bar-pair"><span style:height={`${Math.max(2,row.beforeScore/Math.max(...benchmark.samples.map((r:any)=>r.beforeScore))*100)}%`} title={`Before: ${row.beforeScore}`}></span><span style:height={`${Math.max(1,row.passes.at(-1).score/Math.max(...benchmark.samples.map((r:any)=>r.beforeScore))*100)}%`} title={`After: ${row.passes.at(-1).score}`}></span></div><span>{String(row.seed).padStart(2,'0')}</span></div>{/each}</div><p class="fine-print">Vertical scale normalized to the highest measured score. Individual raw scores are listed below.</p></section><div class="lab-table plain-panel"><h3>Every test, in the open</h3><div class="table-scroll"><table><caption class="visually-hidden">Synthetic evaluation raw results</caption><thead><tr><th>Sample</th><th>Before score</th><th>After score</th><th>Reliable points</th><th>ROI SSIM</th><th>Runtime</th></tr></thead><tbody>{#each benchmark.samples as row}<tr><td>Texture {row.seed}</td><td>{row.beforeScore}</td><td>{row.passes.at(-1).score}</td><td>{row.highQualityBefore} → {row.passes.at(-1).highQuality}</td><td>{row.passes.at(-1).ssim.toFixed(3)}</td><td>{Math.round(row.elapsedMs)} ms</td></tr>{/each}</tbody></table></div></div>{/if}
    {#if independent}<section class="independent-panel plain-panel"><div class="section-heading"><div><h3>A second matcher, the same synthetic test</h3><p>Independent SourceAFIS extraction and matching. Fixed strength 1; seven post-treatment variants per texture.</p></div><a class="text-button" href="/independent.json" download>Raw scores <Icon name="download" size={15}/></a></div><div class="table-scroll"><table><caption class="visually-hidden">Independent matcher results on synthetic textures</caption><thead><tr><th>Matcher</th><th>Baseline matches</th><th>After-treatment matches</th><th>Impostor matches</th></tr></thead><tbody>{#each ['bozorth3','sourceafis'] as name}<tr><td>{name==='sourceafis'?'SourceAFIS 3.18.1':'NBIS Bozorth3'}</td><td>{independent[name].summary.baselineMatches} / {independent[name].summary.baselinePairs}</td><td>{independent[name].summary.attackerMatchesAfter} / {independent[name].summary.attackerPairsAfter}</td><td>{independent[name].summary.impostorMatches} / {independent[name].summary.impostorPairs}</td></tr>{/each}</tbody></table></div><p class="fine-print">The provisional line is 40 for each matcher; their numerical scales differ. Sixty-six synthetic impostor pairs cannot calibrate a 0.1% false match rate. This is evidence about procedural textures, not human fingerprints.</p></section>{/if}
    <section class="limitations plain-panel"><span class="round-icon"><Icon name="info" size={23}/></span><div><h3>What this does not prove</h3><p>The line at 40 is provisional, not calibrated at 0.1% false match rate. The NFIQ-style grade is a heuristic. SourceAFIS has a separate synthetic check below. Learned super-resolution, human contactless images, distance tests, blind perception tests, and target-device performance are not validated.</p><p>Strong treatment visibly reduces ridge detail in a close-up. Full-photo similarity depends on how much of the photo is treated. A low matcher score is not a universal protection guarantee.</p></div></section>
   {:else}
    <section class="page-intro"><div><div class="intro-kicker"><span class="small-line"></span>Small details. Lasting consequences.</div><h1>You can’t reset a fingerprint.</h1><p>Smudge explores a simple question: can we share a photo while sharing less identity?</p></div></section>
    <section class="why-hero"><div><h2>A photo can carry<br/>more than a memory.</h2><p>Exposed ridge detail can be useful to fingerprint analysis. That does not mean every peace-sign selfie can unlock a phone. Image quality, distance, the matcher, and a target sensor all matter.</p><button class="button primary" onclick={()=>navigate('scan')}>Take a closer look <Icon name="arrow" size={18}/></button></div><div class="why-art"><Fingerprint/></div></section>
    <div class="timeline"><article><span>2014</span><div><h3>A fingerprint from photographs</h3><p>The Chaos Computer Club described reconstructing a German minister’s thumbprint from publicly available images.</p><a href="https://www.ccc.de/en/updates/2014/ursel" target="_blank" rel="noreferrer">Read the CCC announcement <Icon name="arrow" size={15}/></a></div></article><article><span>2020</span><div><h3>Research into finger-selfie privacy</h3><p>Researchers explored privacy-preserving anonymization of finger selfies. Smudge builds on an existing research problem; it does not claim to invent it.</p><a href="https://openaccess.thecvf.com/content_CVPRW_2020/html/w48/Malhotra_On_Privacy_Preserving_Anonymization_of_Finger-Selfies_CVPRW_2020_paper.html" target="_blank" rel="noreferrer">Read the CVPR workshop paper <Icon name="arrow" size={15}/></a></div></article><article><span>Today</span><div><h3>A smaller footprint, by choice</h3><p>Smudge brings local analysis, ridge suppression and inspectable matcher results together. It is a defensive prototype with clear validation limits.</p><button class="text-button" onclick={()=>navigate('lab')}>See the evidence and limitations <Icon name="arrow" size={15}/></button></div></article></div>
    <section class="ethics-note plain-panel"><Icon name="shield" size={30}/><div><h3>Built for defence. Built around consent.</h3><p>Only process images you own or have permission to use. Smudge does not export minutiae, print crops, or clone templates. Reports contain measurements, not ridge coordinates. Original photos stay in memory, and reloading clears the session.</p></div></section>
   {/if}
   <footer class="page-footer"><span class="footer-brand"><Icon name="finger" size={16}/> smudge.</span><span>A little less trace. A little more peace of mind.</span><button onclick={()=>navigate('proof')}><Icon name="lock" size={12}/> Private by architecture</button></footer>
  </main>
 </div>
 <nav class="mobile-nav" aria-label="Mobile navigation">{#each nav as item}<button class:active={tab===item.id} onclick={()=>navigate(item.id)} aria-current={tab===item.id?'page':undefined}><Icon name={item.icon} size={21}/><span>{item.id==='scan'?'Scan':item.id==='documents'?'Docs':item.id==='proof'?'Proof':item.id==='lab'?'Lab':'Why'}</span></button>{/each}</nav>
 {#if showScore}<div class="modal-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)showScore=false;}}><div use:focusModal class="modal" role="dialog" aria-modal="true" aria-labelledby="score-title" tabindex="-1"><button class="icon-button modal-close" onclick={()=>showScore=false} aria-label="Close scoring explanation"><Icon name="close"/></button><span class="round-icon"><Icon name="lab" size={24}/></span><h2 id="score-title">A signal, not a prediction.</h2><p>The exposure score summarizes ridge detail. It is not the probability that someone can steal your fingerprint.</p><code class="formula">100 × (0.55 × min(HQ / 40, 1)<br/> + 0.30 × coherent area<br/> + 0.15 × (5 − quality grade) / 4)</code><p>HQ means minutiae with NIST reliability ≥ 0.5. Coherent area is the fraction of blocks with directional ridge structure. The quality grade is a simple heuristic, not trained NFIQ.</p><p>Minimal &lt; 20; Low 20–44; High 45–74; Critical ≥ 75. These tiers are provisional. A reference is needed for an independent match comparison.</p><button class="button primary full" onclick={()=>showScore=false}>Got it</button></div></div>{/if}
 {#if loupe&&image}<div class="modal-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget)loupe=null;}}><div use:focusModal class="modal loupe-modal" role="dialog" aria-modal="true" aria-labelledby="loupe-title" tabindex="-1"><button class="icon-button modal-close" onclick={()=>loupe=null} aria-label="Close print inspection"><Icon name="close"/></button><h2 id="loupe-title">{loupe.label}</h2><p>Inspect the selection. Only actual NIST ridge points are overlaid after analysis.</p><div class="loupe-image" style:aspect-ratio={`${loupe.w}/${loupe.h}`}><img src={image.url} alt="Selected print region, magnified for inspection" style:width={`${image.width/loupe.w*100}%`} style:max-width="none" style:left={`${-loupe.x/loupe.w*100}%`} style:top={`${-loupe.y/loupe.h*100}%`}/>{#each scan?.prints.find(p=>p.region.id===loupe!.id)?.minutiae.filter(m=>m.reliability>=.5)??[] as m}<i class="minutia-dot" style:left={`${m.x/loupe.w*100}%`} style:top={`${m.y/loupe.h*100}%`}></i>{/each}</div><p class="fine-print">No print-crop export. This view stays on your device.</p></div></div>{/if}
</div>
<svelte:window onkeydown={e=>{if(e.key==='Escape'){showScore=false;loupe=null;drawing=false;draft=null;drawStart=null;}}}/>
